from pathlib import Path
import json,shutil,os,statistics
from tools.sloppy_core.benchmark_apps import execute,prepare_clock,run,digest
root=Path.cwd();w=Path('/tmp/dewy-source-core/sra64-runtime');w.mkdir(exist_ok=True)
state=json.loads((root/'__dewycache__/compact-core/current.json').read_text())
compilers={'baseline':root/'__dewycache__/compact-core'/state['binary'], 'candidate':Path('/tmp/dewy-source-core/sra64/bin/dewy-core')}
shutil.copy2(root/'tools/sloppy_core/benchmark_harness.jo',w)
harness=prepare_clock(w,'thread-cpu')
common='''from p"benchmark_harness.jo" import clock, size_argument
Pair:type=[x:TYPE y:TYPE]
advance=(p:Pair):>Pair=>Pair(x=p.x+ONE y=p.y+p.x)
kernel=(count:int64):>int64=>{
let p=Pair(x=ONE y=ZERO)
loop i in [0..count) {p=advance(p)}
return int(p.x+p.y)
}
main=(args:array<string>)=>{
let count=size_argument(args 10000000)
let start=clock() let result=kernel(count) let finish=clock()
printl"{result} {finish-start}"
return 0
}
'''
variants={'int64':common.replace('TYPE','int64').replace('ONE','1').replace('ZERO','0'),
          'float64':common.replace('TYPE','float64').replace('ONE','1.0').replace('ZERO','0.0')}
env={k:v for k,v in os.environ.items() if not k.startswith(('DEWY_','SLOPPY_'))};env['SLOPPY_EMIT_WORKERS']='1'
timings={k:{v:[] for v in compilers} for k in variants};checks={}
for name,source in variants.items():
 p=w/(name+'.dewy');p.write_text(source)
 for label,compiler in compilers.items():run([compiler,'build',p,'--release','-o',w/(name+'-'+label)],env)
for count in [0,1,2,1000,10000000]:
 expected=count+1+count*(count+1)//2;checks[str(count)]=expected
 for name in variants:
  for label in compilers:
   value,_=execute(w/(name+'-'+label),count,env);assert value==expected,(name,label,count,value,expected)
for sample in range(8):
 for name in variants:
  for label in list(compilers)[::1 if sample%2==0 else -1]:
   value,t=execute(w/(name+'-'+label),10000000,env);assert value==checks['10000000']
   if sample:timings[name][label].append(t)
report={'compilers':{k:{'path':str(v),'sha256':digest(v)} for k,v in compilers.items()},'clock':'thread-cpu','count':10000000,'samples':7,'preflight_checksums':checks,'sources':variants,'harness_hashes':harness,'timings':timings,'median_ms':{k:{label:statistics.median(x['kernel_ns'] for x in ts)/1e6 for label,ts in v.items()} for k,v in timings.items()},'script':Path(__file__).read_text(),'load':os.getloadavg()}
Path('/tmp/dewy-source-core/sra64-runtime.json').write_text(json.dumps(report,indent=2)+'\n'); print(report['median_ms'])
